// Presentation only: order, quality, pace and availability come from the collector.
function modelNumber(value) {
  if (value === null || value === undefined || value === '') { return null; }
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}
function modelSpan(seconds) {
  if (seconds <= 0) { return 'now'; }
  const minutes = Math.max(1, Math.round(seconds / 60));
  if (minutes < 60) { return minutes + 'm'; }
  if (minutes < 1440) { return Math.floor(minutes / 60) + 'h ' + minutes % 60 + 'm'; }
  return Math.round(minutes / 144) / 10 + 'd';
}
function modelPace(state, delta, left, window) {
  if (left !== null && left <= 0) { return {text: '✕ spent', cls: 'spent'}; }
  if (/session|hour|daily|minute/i.test(window)) { return {text: '', cls: 'on_pace'}; }
  const magnitude = delta === null ? '' : (Math.round(Math.abs(delta) * 10) / 10) + ' ';
  const states = {
    ahead: {text: '▲ ' + magnitude + 'ahead', cls: 'ahead'},
    on_pace: {text: '● on pace', cls: 'on_pace'},
    behind: {text: '▼ ' + magnitude + 'behind', cls: 'behind'},
    far_behind: {text: '▼ ' + magnitude + 'behind', cls: 'far_behind'},
  };
  return states[state] || {text: '', cls: 'unknown'};
}
context.handlebars.registerHelper('selectionModels', function(rows, now) {
  const models = new Map();
  for (const row of rows || []) {
    if (!row || !row.model || !row.provider) { continue; }
    const key = row.category + '|' + row.provider + '|' + row.model;
    let model = models.get(key);
    if (!model) { model = {...row, numbers: {}}; models.set(key, model); }
    model.numbers[row.field] = modelNumber(row.value);
  }
  const providerNames = {
    google: 'Google', nvidia: 'NVIDIA', groq: 'Groq', kilo: 'Kilo', 'kilo-keyed': 'Kilo (keyed)',
    openrouter: 'OpenRouter', 'cloudflare-workers-ai': 'Cloudflare', cohere: 'Cohere',
    requesty: 'Requesty', orcarouter: 'OrcaRouter', zai: 'Z.ai', vercel: 'Vercel',
    ovh: 'OVH', poolside: 'Poolside', upstage: 'Upstage', inception: 'Inception',
    mistral: 'Mistral', opencode: 'OpenCode Zen', 'opencode-go': 'OpenCode Go',
  };
  const icons = {
    google: 'G', nvidia: 'N', groq: 'q', kilo: 'K', 'kilo-keyed': 'K',
    openrouter: '⇄', 'cloudflare-workers-ai': '☁', cohere: 'C', requesty: 'R',
    orcarouter: 'O', zai: 'Z', vercel: '▲', ovh: 'O', poolside: 'P',
    upstage: 'U', inception: 'I', mistral: 'M', opencode: 'Z', 'opencode-go': '{}',
  };
  const status = {available:'Available',exhausted:'✕ quota spent',excluded:'Excluded',unavailable:'Unavailable'};
  return Array.from(models.values()).sort((a,b) =>
    (a.numbers.position || Number.MAX_SAFE_INTEGER) - (b.numbers.position || Number.MAX_SAFE_INTEGER)
  ).map(model => {
    const n = model.numbers;
    const left = n.remaining_ratio;
    const pace = modelPace(model.pace_state, n.pace_delta ?? null, left ?? null, model.window || '');
    const reset = n.reset_timestamp_seconds;
    const moment = modelNumber(now);
    const relative = reset === undefined || reset === null || moment === null ? '' : modelSpan(reset - moment / 1000);
    const resetText = relative ? (relative === 'now' ? 'resets now' : 'resets in ' + relative) : '';
    const hasLeft = left !== undefined && left !== null;
    const width = hasLeft ? Math.max(0, Math.min(100, Math.round(left * 100))) : 0;
    const fillClass = left !== null && left <= 0 ? 'spent' : (pace.cls === 'behind' || pace.cls === 'far_behind' ? 'behind' : (pace.cls === 'ahead' ? 'ahead' : ''));
    const isExhausted = model.state === 'exhausted' || (left !== null && left <= 0);
    const isRestricted = model.state !== 'available' || model.trust !== 'trusted' || isExhausted;
    return {
      ...model,
      key: model.provider + ':' + model.model,
      providerName: providerNames[model.provider] || model.provider,
      icon: icons[model.provider] || String(model.provider).charAt(0).toUpperCase(),
      defaultWorker: n.default === 1,
      preferred: n.pool_position === 1 && model.state === 'available',
      position: n.position,
      providerPosition: n.provider_position,
      poolPosition: n.pool_position,
      quality: n.quality === undefined || n.quality === null ? 'Unknown' : String(n.quality),
      rounds: n.quality_rounds === undefined || n.quality_rounds === null ? 'rounds unknown' : (
        n.quality_rounds === 0 ? 'no rounds yet' : n.quality_accepted + '/' + n.quality_rounds + ' accepted'),
      percent: hasLeft ? (Math.round(left * 1000) / 10) + '% left' : 'No long-window reading',
      hasLeft: hasLeft,
      width: width,
      fillClass: fillClass,
      windowName: model.window ? String(model.window).replaceAll('_',' ') : 'Capacity',
      paceText: pace.text,
      paceClass: pace.cls,
      resetText: resetText,
      customReset: model.reset_source === 'custom' ? 'custom reset' : '',
      statusText: isExhausted ? '✕ quota spent' : (status[model.state] || 'Unknown'),
      reasonText: String(model.reason || '').replaceAll('_',' '),
      restricted: isRestricted,
      effortText: model.effort || 'not offered',
    };
  });
});

