.capacity { font-size: 13px; width: 100%; }
.capacity .hdr { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 12px; }
.capacity .chip { font-size: 11px; border: 1px solid #6b6f7a; border-radius: 999px; padding: 2px 8px; color: #c9ccd3; white-space: nowrap; }
.capacity .asof { margin-left: auto; font-size: 11px; color: #8b8f99; }
.capacity .grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; }
.capacity .card { display: grid; grid-template-columns: max-content minmax(48px, 1fr) auto; column-gap: 8px; align-items: center; background: #181a20; border: 1px solid #262932; border-radius: 8px; padding: 12px; min-width: 0; }
.capacity .ph { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; margin-bottom: 8px; min-width: 0; }
.capacity .ico { width: 22px; height: 22px; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700; flex: none; }
.capacity .pn { font-weight: 600; font-size: 13px; white-space: nowrap; flex: none; }
.capacity .ra { font-size: 10.5px; color: #8b8f99; white-space: nowrap; flex: none; }
.capacity .pm { font-size: 11px; color: #8b8f99; margin-left: auto; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.capacity .win { display: contents; }
.capacity .wl { font-size: 11px; color: #b5b8c0; white-space: nowrap; margin-top: 7px; }
.capacity .bar { position: relative; height: 8px; background: #2a2d36; border-radius: 4px; margin-top: 7px; }
.capacity .fill { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 4px; background: #5b9bd5; }
.capacity .fill.behind { background: #e0a03a; }
.capacity .fill.spent { background: #d9534f; }
.capacity .tick { position: absolute; top: -3px; bottom: -3px; width: 2px; background: #e6e6ea; border-radius: 1px; }
.capacity .pct { font-size: 12px; text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; margin-top: 7px; }
.capacity .sub { grid-column: 1 / -1; font-size: 10.5px; color: #8b8f99; white-space: nowrap; margin: 1px 0 2px; }
.capacity .sub:empty { display: none; }
.capacity .sub .ahead { color: #8fc98f; }
.capacity .sub .behind { color: #e0a03a; }
.capacity .sub .spent { color: #d9534f; }
.capacity .sub .brief { display: none; }
.capacity .tag { font-size: 10px; border-radius: 4px; padding: 1px 6px; margin-left: 6px; background: #3a3423; color: #e0c27a; white-space: nowrap; }
.capacity .fr { grid-column: 1 / -1; font-size: 10.5px; color: #8b8f99; margin-top: 8px; white-space: nowrap; }
.capacity .fr.ok { color: #8fc98f; }
.capacity .learn { font-size: 11px; line-height: 1.55; color: #b5b8c0; margin-top: 10px; }
.capacity .note { font-size: 11px; color: #8b8f99; margin-top: 6px; }
@media (max-width: 520px) {
  .capacity .asof { display: none; }
  .capacity .card { grid-template-columns: max-content minmax(40px, 1fr) auto; }
  .capacity .sub .wide { display: none; }
  .capacity .sub .brief { display: inline; }
}

.capacity .hdr {display:none} .capacity .ph {flex-wrap:wrap} .capacity .sub,.capacity .fr {white-space:normal;overflow-wrap:anywhere} .capacity .sub.ahead {color:#8fc98f} .capacity .sub.behind {color:#e0a03a} .capacity .sub.far_behind,.capacity .sub.spent {color:#d9534f}

